package algorithms.bytecode;

/**
 * ============================================================================
 * Java Bytecode Demonstration Class
 * ============================================================================
 * 
 * Demonstrates how standard Java high-level operations compile down to 
 * stack-based Java Virtual Machine (JVM) bytecode instructions.
 * 
 * To inspect the generated bytecode:
 *   javac algorithms/bytecode/BytecodeDemo.java
 *   javap -c -v algorithms.bytecode.BytecodeDemo
 * ============================================================================
 */
public class BytecodeDemo {

    /**
     * Demonstrates local variable loading, stack addition, and storing.
     * Bytecode:
     *   iload_1       // Push local variable 1 (a) onto operand stack
     *   iload_2       // Push local variable 2 (b) onto operand stack
     *   iadd          // Pop both integers, compute sum, push result
     *   istore_3      // Pop result and store into local variable 3 (sum)
     *   iload_3       // Push sum onto stack
     *   ireturn       // Return integer value from stack
     */
    public static int add(int a, int b) {
        int sum = a + b;
        return sum;
    }

    /**
     * Demonstrates conditional branching and comparison.
     * Bytecode:
     *   iload_0       // Push a
     *   iload_1       // Push b
     *   if_icmple ... // Branch if a <= b
     *   iload_0       // Return a if greater
     *   ireturn
     */
    public static int max(int a, int b) {
        if (a > b) {
            return a;
        } else {
            return b;
        }
    }

    /**
     * Demonstrates loop counter, comparison, and backward goto branching.
     * Bytecode:
     *   iconst_0      // Push 0 (sum)
     *   istore_1      // Store sum
     *   iconst_1      // Push 1 (i)
     *   istore_2      // Store i
     *   iload_2       // Loop condition check: i <= n
     *   iload_0
     *   if_icmpgt ... // If i > n, break loop
     *   ...
     *   goto ...      // Repeat loop
     */
    public static int computeSumUpTo(int n) {
        int total = 0;
        for (int i = 1; i <= n; i++) {
            total += i;
        }
        return total;
    }

    public static void main(String[] args) {
        int a = 15;
        int b = 25;
        int sum = add(a, b);
        int maximum = max(a, b);
        int cumulative = computeSumUpTo(5);

        System.out.println("--- Java Bytecode Execution Demo ---");
        System.out.println("add(" + a + ", " + b + ") = " + sum);
        System.out.println("max(" + a + ", " + b + ") = " + maximum);
        System.out.println("computeSumUpTo(5) = " + cumulative);
    }
}
